Registro Alumno
  Definir nombre Como Cadena;
  Definir nota Como Real;
FinRegistro
Algoritmo Ficha
  Definir ana Como Alumno <- Alumno("Ana", 8.5);
  ana.nota <- ana.nota + 1;
  Escribir ana.nombre, ": ", ana.nota;
FinAlgoritmo

Registro Casilla
  Definir fila, columna Como Entero;
FinRegistro
Algoritmo Tablero
  Definir a Como Casilla <- Casilla(1, 2);
  Definir b Como Casilla <- a;
  b.fila <- 10;
  Escribir a.fila, " ", b.fila, " ", a = b;
FinAlgoritmo

Registro Casilla
  Definir fila, columna Como Entero;
FinRegistro
Algoritmo EscribirRegistro
  Escribir Casilla(1, 2);
FinAlgoritmo

Registro Casilla
  Definir fila, columna Como Entero;
FinRegistro
Algoritmo Faltan
  Definir c Como Casilla <- Casilla(1);
FinAlgoritmo
